<?php
require __DIR__.'/functions.php'; boot();
$c=cfg(); $pdo=db(); $notice='';
if(isset($_POST['login'])) { if(hash_equals($c['admin_user'],(string)($_POST['username']??'')) && password_verify((string)($_POST['password']??''),$c['admin_password_hash'])) {session_regenerate_id(true);$_SESSION['ok']=true;} else $notice='Wrong login.'; }
if(isset($_POST['logout'])) {auth();check_csrf();$_SESSION=[];session_destroy();header('Location: index.php');exit;}
if(!empty($_SESSION['ok']) && $_SERVER['REQUEST_METHOD']==='POST' && !isset($_POST['logout']) && !isset($_POST['login'])) { check_csrf();
 try {
 if(isset($_POST['upload'])) { if(!is_uploaded_file($_FILES['csv']['tmp_name']??'')) throw new RuntimeException('Please choose a CSV.'); $f=fopen($_FILES['csv']['tmp_name'],'r');$n=0; $ins=$pdo->prepare('INSERT OR IGNORE INTO contacts(phone,name,consent) VALUES (?,?,1)');while(($row=fgetcsv($f))!==false){$phone=norm_phone((string)($row[0]??''));if(!$phone)continue;$ins->execute([$phone,substr((string)($row[1]??''),0,100)]);$n+=$ins->rowCount();}fclose($f);$notice="Imported $n new consented contacts; duplicates skipped."; }
 if(isset($_POST['new_campaign'])) { $t=trim((string)($_POST['template']??''));$title=trim((string)($_POST['title']??''));$lang=trim((string)($_POST['language']??'en'));$url=trim((string)($_POST['url']??''));$image=trim((string)($_POST['image']??''));$limit=min(10000,max(1,(int)($_POST['daily']??500)));if(!preg_match('/^[a-z0-9_]{1,512}$/',$t)||!preg_match('/^[a-zA-Z_]{2,12}$/',$lang)||$title==='')throw new RuntimeException('Invalid template, language, or title.');foreach([$url,$image] as $u) if($u!==''&&(!filter_var($u,FILTER_VALIDATE_URL)||!str_starts_with($u,'https://')))throw new RuntimeException('Links must be valid HTTPS URLs.');$pdo->prepare('INSERT INTO campaigns(title,template_name,language,website_url,image_url,daily_limit) VALUES(?,?,?,?,?,?)')->execute([$title,$t,$lang,$url,$image,$limit]);$notice='Campaign created (paused).'; }
 if(isset($_POST['toggle'])) { $id=(int)$_POST['toggle'];$pdo->prepare('UPDATE campaigns SET running=CASE WHEN running=1 THEN 0 ELSE 1 END WHERE id=?')->execute([$id]);$notice='Campaign status changed.'; }
 if(isset($_POST['optout'])) { $phone=norm_phone((string)($_POST['phone']??''));if(!$phone)throw new RuntimeException('Invalid number.');$pdo->prepare('UPDATE contacts SET opted_out=1 WHERE phone=?')->execute([$phone]);$notice='Opt-out saved.'; }
 }catch(Throwable $e){$notice='Error: '.$e->getMessage();}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clothing Campaign Manager</title><style>body{font-family:system-ui,Arial;margin:0;background:#f3f6fa;color:#152033}main{max-width:1020px;margin:40px auto;padding:0 18px}h1{font-size:28px}section{background:white;margin:18px 0;padding:24px;border-radius:14px;box-shadow:0 4px 20px #172b4d10}input,button{font:inherit;padding:11px;margin:6px 4px 6px 0;border:1px solid #cbd5e1;border-radius:8px}input{max-width:100%;box-sizing:border-box}button{background:#075e54;color:#fff;border:0;cursor:pointer}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:10px;border-bottom:1px solid #eee}small{color:#58677b}.note{background:#eaf5ed;padding:14px;border-radius:8px}label{display:inline-block;margin:5px 9px 5px 0}label input{display:block;min-width:170px}</style></head><body><main><h1>Clothing Campaign Manager</h1><p>Meta Cloud API · consented contacts only · per-campaign deduplication</p><?php if($notice):?><p class="note"><?=h($notice)?></p><?php endif;?>
<?php if(empty($_SESSION['ok'])): ?><section><h2>Admin login</h2><form method="post"><input name="username" placeholder="Username" required><input type="password" name="password" placeholder="Password" required><button name="login" value="1">Sign in</button></form></section>
<?php else: $contacts=(int)$pdo->query('SELECT count(*) FROM contacts WHERE consent=1 AND opted_out=0')->fetchColumn();$stats=$pdo->query("SELECT state,count(*) AS n FROM sends GROUP BY state")->fetchAll(); $campaigns=$pdo->query('SELECT * FROM campaigns ORDER BY id DESC')->fetchAll(); ?>
<form method="post" style="text-align:right"><input type="hidden" name="csrf" value="<?=csrf()?>"><button name="logout" value="1">Logout</button></form><section><h2>Overview</h2><p><strong><?=number_format($contacts)?></strong> eligible contacts; <?=h(json_encode($stats))?></p><small>Daily cap is additionally restricted by Meta account limits, recipient eligibility and configurable total budget. An API acceptance is not proof of delivery.</small></section>
<section><h2>1 · Upload opted-in contacts</h2><p>CSV: first column phone in 923001234567 format, second column optional name. Only upload clients with documented WhatsApp marketing permission.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="file" name="csv" accept=".csv,text/csv" required><button name="upload" value="1">Import CSV</button></form></section>
<section><h2>2 · Create campaign</h2><p>First create and obtain approval for the exact template in WhatsApp Manager. For URL body parameter, use exactly one {{1}} placeholder; leave website blank if no body variable. Optional image requires an approved image-header template.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Campaign title<input name="title" placeholder="11.11 clothing sale" required></label><label>Approved template name<input name="template" placeholder="sale_1111" required></label><label>Language<input name="language" value="en" required></label><label>Website URL / {{1}}<input name="url" placeholder="https://example.com/sale"></label><label>Public image URL<input name="image" placeholder="https://example.com/banner.jpg"></label><label>Daily maximum<input type="number" name="daily" min="1" max="10000" value="500"></label><button name="new_campaign" value="1">Save (paused)</button></form></section>
<section><h2>3 · Campaigns</h2><table><tr><th>Name</th><th>Template</th><th>Cap/day</th><th>Status</th><th>Action</th></tr><?php foreach($campaigns as $cp):?><tr><td><?=h($cp['title'])?></td><td><?=h($cp['template_name'])?></td><td><?= (int)$cp['daily_limit']?></td><td><?=$cp['running']?'ACTIVE':'PAUSED'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button name="toggle" value="<?=(int)$cp['id']?>"><?=$cp['running']?'Pause':'Activate'?></button></form></td></tr><?php endforeach;?></table></section>
<section><h2>4 · Unsubscribe a contact</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input name="phone" placeholder="923001234567" required><button name="optout" value="1">Opt out</button></form></section>
<section><h2>Before activating</h2><p>Set credentials in config.php; test using a test number and Meta-approved template; review daily allowance and spending guard; configure webhook and cron. Sending remains disabled until enable_live_sending=true.</p></section><?php endif;?></main></body></html>
